import java.io.BufferedReader; import java.io.InputStreamReader; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String tag = br.readLine(); if (tag == null || tag.length() != 9) { System.out.println("invalid"); return; } char letter = tag.charAt(2); if ("AEIOUY".indexOf(letter) != -1) { System.out.println("invalid"); return; } int[] indices = {0, 1, 3, 4, 4, 5, 7, 8}; for (int i = 0; i < indices.length; i += 2) { int d1 = tag.charAt(indices[i]) - '0'; int d2 = tag.charAt(indices[i + 1]) - '0'; if ((d1 + d2) % 2 != 0) { System.out.println("invalid"); return; } } System.out.println("valid"); } }